// Measures the JavaScript each route really loads, and what each library costs on the route that uses it.
//
//   npm run build && npm run measure              route totals (what size-limit checks)
//   CRASHCOURT_SOURCEMAPS=1 npm run build && npm run measure
//                                                 route totals plus per-library attribution
//
// Per route:
//   initial  the JavaScript the exported HTML loads (what the budgets call "initial JavaScript")
//   total    initial plus the route's own lazy chunks (React Flow on the lineage route)
//   loaded   every script the browser fetched once the page settled; this also counts chunks of
//            linked routes that the router fetches ahead of a click, which total leaves out
// "total" is measured with the router's prefetch requests blocked (the HEAD check and the `_rsc` segment
// fetches it makes for links on the page), so only the route's own code loads. Sizes are gzip level 9 per
// file, summed, as size-limit computes them. Results go to .budgets/.
//
// Attribution maps every generated byte back to its source through the source maps and groups the
// sources by npm package. A library's cost is the gzip size of its bytes concatenated on their own,
// which slightly overstates what it adds in place (gzip shares context across a file); BUDGETS.md says so.

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";

import { TraceMap, decodedMappings } from "@jridgewell/trace-mapping";
import { chromium } from "@playwright/test";

import { serve } from "./serve.ts";

const SITE = fileURLToPath(new URL("..", import.meta.url));
const OUT = path.join(SITE, "out");
const BUDGETS = path.join(SITE, ".budgets");
const PORT = 4175;

// Routes by pattern; a dynamic route is measured on its first exported page.
export const PATTERNS: readonly { pattern: string; waitFor?: string }[] = [
  { pattern: "/" },
  { pattern: "/matrix" },
  { pattern: "/trials/[cell]/[trial]" },
  { pattern: "/lineage/[trial]/[thread]", waitFor: ".react-flow" },
  { pattern: "/findings/[id]" },
  { pattern: "/compare/[scenario]" },
  { pattern: "/methodology" },
];

/** The first exported page of a route pattern, as a URL path ending in "/". */
function firstPage(pattern: string): string {
  let dirs = [""];
  for (const segment of pattern.split("/").filter(Boolean)) {
    dirs = dirs.flatMap((d) =>
      segment.startsWith("[")
        ? readdirSync(path.join(OUT, d), { withFileTypes: true })
            .filter((e) => e.isDirectory() && !e.name.startsWith("__next"))
            .map((e) => `${d}/${e.name}`)
            .sort()
        : [`${d}/${segment}`],
    );
  }
  const page = dirs.find((d) => existsSync(path.join(OUT, d, "index.html")));
  if (page === undefined) throw new Error(`no exported page for ${pattern}`);
  return `${page}/`;
}

interface Route {
  pattern: string;
  page: string;
  waitFor?: string;
}

const ROUTES = (): Route[] => PATTERNS.map((p) => ({ ...p, page: firstPage(p.pattern) }));

// The libraries the card asks about, each measured with its dependency closure (found below). A group
// counts dependencies the libraries share once.
const LIBRARIES: readonly (readonly string[])[] = [
  ["d3-scale"],
  ["d3-zoom"],
  ["d3-scale", "d3-zoom"],
  ["@xyflow/react"],
];

// The budget targets, in kB.
const SPEC_TARGETS: Record<string, number> = {
  "/ initial": 150,
  "/lineage/[trial]/[thread] total": 300,
};

const MAP_COMMENT = /\n?\/\/# sourceMappingURL=\S+\s*$/;

function code(file: string): Buffer {
  const text = readFileSync(path.join(OUT, file), "utf8");
  return Buffer.from(text.replace(MAP_COMMENT, ""), "utf8");
}

const gz = (buf: Buffer | string): number => gzipSync(buf, { level: 9 }).length;

/** Scripts the exported HTML loads in a modern browser (nomodule polyfills are never fetched). */
function htmlScripts(route: string): string[] {
  const html = readFileSync(path.join(OUT, route, "index.html"), "utf8");
  const found = new Set<string>();
  for (const m of html.matchAll(/<script\b[^>]*>/g)) {
    const src = /\ssrc="([^"]+\.js)"/.exec(m[0]);
    if (src && !/\snomodule\b/i.test(m[0])) found.add(src[1]!.replace(/^\//, ""));
  }
  return [...found].sort();
}

const PREFETCH = (url: URL, method: string) =>
  method === "HEAD" || url.searchParams.has("_rsc") || /\/__next\.[^/]*\.txt$/.test(url.pathname);

/** Scripts the browser fetched on each route's page, keyed by route pattern. */
async function fetchedScripts(
  routes: readonly Route[],
  blockPrefetch: boolean,
): Promise<Map<string, string[]>> {
  const server = await serve(PORT);
  const browser = await chromium.launch();
  const result = new Map<string, string[]>();
  try {
    for (const { pattern, page: url, waitFor } of routes) {
      const context = await browser.newContext();
      if (blockPrefetch) {
        await context.route("**/*", (r) =>
          PREFETCH(new URL(r.request().url()), r.request().method()) ? r.abort() : r.continue(),
        );
      }
      const page = await context.newPage();
      const seen = new Set<string>();
      page.on("response", (r) => {
        const u = new URL(r.url());
        if (u.pathname.endsWith(".js") && r.request().resourceType() === "script") {
          seen.add(u.pathname.replace(/^\//, ""));
        }
      });
      await page.goto(`http://127.0.0.1:${PORT}${url}`, { waitUntil: "networkidle" });
      if (waitFor) await page.locator(waitFor).waitFor();
      await page.waitForLoadState("networkidle");
      result.set(pattern, [...seen].sort());
      await context.close();
    }
  } finally {
    await browser.close();
    server.close();
  }
  return result;
}

/** The npm package a source path belongs to, or a bucket for code that is not a package. */
function packageOf(source: string): string {
  const i = source.lastIndexOf("node_modules/");
  if (i === -1)
    return /\[project\]\/(app|components|lib|styles)\//.test(source) ? "(site code)" : "(other)";
  const rest = source.slice(i + "node_modules/".length).split("/");
  return rest[0]!.startsWith("@") ? `${rest[0]}/${rest[1]}` : rest[0]!;
}

/** Splits a generated file into byte runs by the package each run came from. */
function attribute(file: string): Map<string, Buffer[]> | null {
  const raw = readFileSync(path.join(OUT, file), "utf8");
  const ref = /\/\/# sourceMappingURL=(\S+)\s*$/.exec(raw)?.[1];
  const mapFile = ref ? path.join(OUT, path.dirname(file), ref) : path.join(OUT, `${file}.map`);
  if (!existsSync(mapFile)) return null;
  const map = new TraceMap(readFileSync(mapFile, "utf8"));
  const lines = code(file).toString("utf8").split("\n");
  const runs = new Map<string, Buffer[]>();
  const push = (pkg: string, text: string) => {
    if (!text) return;
    const list = runs.get(pkg) ?? [];
    list.push(Buffer.from(text, "utf8"));
    runs.set(pkg, list);
  };
  decodedMappings(map).forEach((segments, lineNo) => {
    const line = lines[lineNo] ?? "";
    if (segments.length === 0) {
      push("(unmapped)", line);
      return;
    }
    push("(unmapped)", line.slice(0, segments[0]![0]));
    segments.forEach((seg, k) => {
      const end = k + 1 < segments.length ? segments[k + 1]![0] : line.length;
      const source = seg.length > 1 ? (map.resolvedSources[seg[1]!] ?? "") : "";
      push(source ? packageOf(source) : "(unmapped)", line.slice(seg[0], end));
    });
  });
  return runs;
}

/** A package and every package it depends on, as installed. */
function closure(name: string, into = new Set<string>()): Set<string> {
  if (into.has(name)) return into;
  into.add(name);
  const manifest = path.join(SITE, "node_modules", name, "package.json");
  if (!existsSync(manifest)) return into;
  const deps = (JSON.parse(readFileSync(manifest, "utf8")) as { dependencies?: object })
    .dependencies;
  for (const dep of Object.keys(deps ?? {})) closure(dep, into);
  return into;
}

interface Sizes {
  files: string[];
  gzip: number;
}

export interface RouteReport {
  page: string;
  initial: Sizes;
  total: Sizes;
  loaded: Sizes;
}

const sized = (files: string[]): Sizes => ({
  files,
  gzip: files.reduce((n, f) => n + gz(code(f)), 0),
});

type Kb = { raw: number; gzip: number };

function measureBytes(bufs: Buffer[]): Kb {
  const joined = Buffer.concat(bufs);
  return { raw: joined.length, gzip: gz(joined) };
}

async function main(): Promise<void> {
  if (!existsSync(OUT)) throw new Error("out/ does not exist; run npm run build first");
  const routes = ROUTES();
  const own = await fetchedScripts(routes, true);
  const loaded = await fetchedScripts(routes, false);
  const report: Record<string, RouteReport> = {};
  for (const { pattern, page } of routes) {
    const initial = htmlScripts(page);
    const union = (more: string[] | undefined) =>
      [...new Set([...initial, ...(more ?? [])])].sort();
    report[pattern] = {
      page,
      initial: sized(initial),
      total: sized(union(own.get(pattern))),
      loaded: sized(union(loaded.get(pattern))),
    };
  }

  // Attribution, when the build has source maps.
  const packagesByRoute: Record<string, Record<string, Kb>> = {};
  const libraries: Record<string, unknown>[] = [];
  let mapped = true;
  for (const { pattern } of routes) {
    const r = report[pattern]!;
    const runsOf = (files: string[]) => {
      const packages = new Map<string, Buffer[]>();
      for (const file of files) {
        const runs = attribute(file);
        if (runs === null) return null;
        for (const [pkg, bufs] of runs) packages.set(pkg, [...(packages.get(pkg) ?? []), ...bufs]);
      }
      return packages;
    };
    const packages = runsOf(r.total.files);
    const initialPackages = runsOf(r.initial.files);
    if (packages === null || initialPackages === null) {
      mapped = false;
      break;
    }
    packagesByRoute[pattern] = Object.fromEntries(
      [...packages]
        .map(([pkg, bufs]) => [pkg, measureBytes(bufs)] as const)
        .sort((a, b) => b[1].raw - a[1].raw),
    );
    for (const group of LIBRARIES) {
      if (!group.every((lib) => packages.has(lib))) continue;
      const members = [...new Set(group.flatMap((lib) => [...closure(lib)]))].filter((p) =>
        packages.has(p),
      );
      libraries.push({
        library: group.join(" + "),
        route: pattern,
        packages: members,
        own: measureBytes(group.flatMap((lib) => packages.get(lib)!)),
        withDependencies: measureBytes(members.flatMap((p) => packages.get(p)!)),
        lazy: !group.some((lib) => initialPackages.has(lib)),
      });
    }
  }

  mkdirSync(BUDGETS, { recursive: true });
  writeFileSync(
    path.join(BUDGETS, "measure.json"),
    JSON.stringify(
      {
        measured_at: new Date().toISOString(),
        platform: `${process.platform} ${process.arch}, node ${process.version}`,
        routes: report,
        attribution: mapped ? { packagesByRoute, libraries } : null,
      },
      null,
      2,
    ) + "\n",
  );

  const kb = (n: number) => `${(n / 1000).toFixed(1)} kB`;
  console.log(`${"route".padEnd(28)}  initial     total    loaded`);
  for (const [pattern, r] of Object.entries(report)) {
    const cols = [r.initial, r.total, r.loaded].map((x) => kb(x.gzip).padStart(9)).join(" ");
    console.log(`${pattern.padEnd(28)}${cols}`);
  }

  // The rule in budgets.json: measured plus 5%, rounded up to a whole kB, capped at the target.
  const budgets = JSON.parse(readFileSync(path.join(SITE, "budgets.json"), "utf8")) as {
    routes: Record<string, Record<string, number>>;
  };
  console.log(`\n${"limit".padEnd(37)}measured  proposed  committed`);
  for (const [pattern, limits] of Object.entries(budgets.routes)) {
    for (const [kind, committed] of Object.entries(limits)) {
      const bytes = report[pattern]?.[kind as keyof RouteReport];
      if (!bytes || typeof bytes === "string") continue;
      const cap = SPEC_TARGETS[`${pattern} ${kind}`] ?? Infinity;
      const proposed = Math.min(Math.ceil((bytes.gzip * 1.05) / 1000), cap);
      const flag = proposed === committed ? "" : "  <- differs";
      console.log(
        `${`${pattern} ${kind}`.padEnd(37)}${kb(bytes.gzip).padStart(8)}${`${proposed} kB`.padStart(10)}${`${committed} kB`.padStart(11)}${flag}`,
      );
    }
  }
  if (!mapped) {
    console.log("\nno source maps in out/; build with CRASHCOURT_SOURCEMAPS=1 for attribution");
    return;
  }
  console.log(`\n${"library on route".padEnd(52)}  own gz  with deps  lazy`);
  type Library = { library: string; route: string; own: Kb; withDependencies: Kb; lazy: boolean };
  for (const l of libraries as Library[]) {
    const name = `${l.library} on ${l.route}`.padEnd(52);
    console.log(
      `${name}${kb(l.own.gzip).padStart(8)}${kb(l.withDependencies.gzip).padStart(11)}  ${l.lazy ? "yes" : "no"}`,
    );
  }
}

if (import.meta.main) await main();
